  var a := 1;
  while (a != M)
    invariant 1 <= a <= M;
  {
    var b := a + 1;
    while (b != M+1)
      invariant a+1 <= b <= M+1;
    {
      var c := M;
      while (c != a)
        invariant a <= c <= M;
      {
        assume X[a-1,a-1] != 0;
        X[b-1, c-1] := X[b-1,c-1] - X[b-1,a-1] / X[a-1,a-1] * X[a-1,c-1];
        c := c - 1;
      }
      b := b + 1;
